/**
 * Unit tests for JacksonAnnotationIntrospector.findContentDeserializer
 */
public class JacksonAnnotationIntrospector_findContentDeserializer_TriageGen0Test {

    private JacksonAnnotationIntrospector introspector;

    // Mock deserializer class for testing
    public static class MockContentDeserializer extends JsonDeserializer<Object> {
        @Override
        public Object deserialize(JsonParser p, com.fasterxml.jackson.databind.DeserializationContext ctxt) {
            return null;
        }
    }

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    /**
     * Test case where the Annotated object has no @JsonDeserialize annotation.
     * Covers the case where _findAnnotation returns null.
     */
    @Test
    public void testFindContentDeserializer_NoAnnotation() {
        Annotated annotated = Mockito.mock(Annotated.class);
        // Note: _findAnnotation is protected/internal, but in a real Jackson environment 
        // it looks for the annotation on the annotated element. 
        // Since we can't easily mock the internal _findAnnotation call of the real object 
        // without PowerMock, we rely on the fact that if the annotation is missing, it returns null.

        // Using a mock that won't return the annotation
        Object result = introspector.findContentDeserializer(annotated);
        assertNull("Should return null when no annotation is present", result);
    }

    /**
     * Test case where @JsonDeserialize is present but contentUsing is JsonDeserializer.None.class.
     * Covers the branch: if (deserClass != JsonDeserializer.None.class)
     */
    @Test
    public void testFindContentDeserializer_WithNoneAnnotation() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        // We need to simulate the behavior of _findAnnotation. 
        // Since we are testing the logic inside findContentDeserializer, 
        // we wrap the logic or use a spy if possible. 
        // However, the standard way to test this without PowerMock is to provide a real Annotated implementation.

        // Given the constraints of the provided code, we simulate the annotation presence.
        // Because _findAnnotation is a method of the class under test, 
        // we use a Spy to control the outcome of _findAnnotation.
        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(JsonDeserializer.None.class);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertNull("Should return null when contentUsing is JsonDeserializer.None", result);
    }

    /**
     * Test case where @JsonDeserialize is present and contentUsing is a valid class.
     * Covers the branch: if (deserClass != JsonDeserializer.None.class) -> return deserClass
     */
    @Test
    public void testFindContentDeserializer_WithValidDeserializer() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(MockContentDeserializer.class);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertEquals("Should return the deserializer class", MockContentDeserializer.class, result);
    }

    /**
     * Test case where @JsonDeserialize is present but contentUsing returns null.
     * Covers the edge case where the annotation exists but the property is null.
     */
    @Test
    public void testFindContentDeserializer_WithNullContentUsing() {
        Annotated annotated = Mockito.mock(Annotated.class);
        JsonDeserialize ann = Mockito.mock(JsonDeserialize.class);

        JacksonAnnotationIntrospector spyIntrospector = Mockito.spy(new JacksonAnnotationIntrospector());

        when(spyIntrospector._findAnnotation(annotated, JsonDeserialize.class)).thenReturn(ann);
        when(ann.contentUsing()).thenReturn(null);

        Object result = spyIntrospector.findContentDeserializer(annotated);
        assertNull("Should return null if contentUsing is null", result);
    }
}
